tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "read_transcript",
    "description": "Liest das kanonisch nummerierte Transkript erneut (optional nur den Bereich fromUnit..toUnit, 1-basierte Unit-Nummern). Nutze es, wann immer du etwas nachpruefen willst.",
    "parameters": {
      "type": "object",
      "properties": {
        "fromUnit": {
          "type": [
            "integer",
            "null"
          ],
          "default": null
        },
        "toUnit": {
          "type": [
            "integer",
            "null"
          ],
          "default": null
        }
      }
    }
  },
  {
    "type": "function",
    "name": "validate_draft",
    "description": "Prueft Entwurf \u002B Quellenbilanz deterministisch (Schema, Typen, existierende AU-Referenzen, Duplikate, Bilanz-Vollstaendigkeit) und gibt eine Fehlerliste zurueck \u2014 beliebig oft nutzbar.",
    "parameters": {
      "type": "object",
      "properties": {
        "statements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string"
              },
              "statement": {
                "type": "string"
              },
              "type": {
                "type": "string"
              },
              "sourceUnitIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "derivation": {
                "type": "string"
              },
              "uncertainty": {
                "type": "string"
              }
            },
            "required": [
              "id",
              "statement",
              "type",
              "sourceUnitIds",
              "derivation",
              "uncertainty"
            ]
          }
        },
        "quellenbilanz": {
          "type": [
            "array",
            "null"
          ],
          "items": {
            "type": [
              "object",
              "null"
            ],
            "properties": {
              "auId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "disposition": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "claimIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": [
                    "string",
                    "null"
                  ]
                },
                "default": null
              }
            },
            "required": [
              "auId",
              "disposition"
            ]
          },
          "default": null
        }
      },
      "required": [
        "statements"
      ]
    }
  },
  {
    "type": "function",
    "name": "submit_result",
    "description": "GENAU EINMAL am Ende: reicht Endergebnis \u002B vollstaendige Quellenbilanz ein. Validierung ist HART (Fehlerliste zurueck = nachbessern und erneut einreichen). Erst eine GUELTIGE Einreichung beendet die Aufgabe.",
    "parameters": {
      "type": "object",
      "properties": {
        "statements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string"
              },
              "statement": {
                "type": "string"
              },
              "type": {
                "type": "string"
              },
              "sourceUnitIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "derivation": {
                "type": "string"
              },
              "uncertainty": {
                "type": "string"
              }
            },
            "required": [
              "id",
              "statement",
              "type",
              "sourceUnitIds",
              "derivation",
              "uncertainty"
            ]
          }
        },
        "quellenbilanz": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "auId": {
                "type": "string"
              },
              "disposition": {
                "type": "string"
              },
              "claimIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                },
                "default": null
              }
            },
            "required": [
              "auId",
              "disposition"
            ]
          }
        }
      },
      "required": [
        "statements",
        "quellenbilanz"
      ]
    }
  }
]
